        "index.ts": "import {\n    Alignment,\n    Column,\n    Container,\n    CrossAxisAlignment,\n    component,\n    derive,\n    mutate,\n    PointerInteract,\n    source,\n    Text,\n} from \"@tur/edgy\";\nimport { COLORS } from \"./utils\";\n\nconst count$ = source(0);\n\nexport default component(() =>\n    Container({\n        color: COLORS.bg,\n        children: [\n            Column({\n                crossAlignment: CrossAxisAlignment.Center,\n                children: [\n                    Text({\n                        text: derive((g) => `Multi-file count: ${g(count$)}`),\n                        fontSize: 24,\n                        color: COLORS.text,\n                    }),\n                    PointerInteract({\n                        onClick: mutate(({ get, set }, _ev) =>\n                            set(count$, get(count$) + 1),\n                        ),\n                        child: Container({\n                            width: 120,\n                            height: 44,\n                            borderRadius: 8,\n                            color: COLORS.primary,\n                            alignment: Alignment.Center,\n                            children: [\n                                Text({\n                                    text: \"+1\",\n                                    fontSize: 18,\n                                    color: COLORS.white,\n                                }),\n                            ],\n                        }),\n                    }),\n                ],\n            }),\n        ],\n    }),\n);\n",
        "utils.ts": "// utils.ts — shared helper for the multi-file demo case.\nimport { Color } from \"@tur/edgy\";\n\nexport const COLORS = {\n    primary: Color.hex(\"#6366f1\"),\n    bg: Color.hex(\"#f8fafc\"),\n    text: Color.hex(\"#1e293b\"),\n    white: Color.hex(\"#ffffff\"),\n};\n",
