    "switch-demo": {
        "index.ts": "import {\n    Alignment,\n    Color,\n    Column,\n    Container,\n    CrossAxisAlignment,\n    component,\n    derive,\n    Expanded,\n    get,\n    MainAxisAlignment,\n    mutate,\n    PointerInteract,\n    Row,\n    Switch,\n    source,\n    Text,\n} from \"@tur/edgy\";\n\nconst tab$ = source(\"red\");\n\nconst TABS = [\"red\", \"green\", \"blue\"] as const;\nconst HEX: Record<string, string> = {\n    red: \"#ef4444\",\n    green: \"#22c55e\",\n    blue: \"#3b82f6\",\n};\n\nfunction coloredPanel(label: string, hex: string) {\n    return Container({\n        color: Color.hex(hex),\n        alignment: Alignment.Center,\n        children: [\n            Text({\n                text: label,\n                fontSize: 36,\n                color: Color.hex(\"#ffffff\"),\n            }),\n        ],\n    });\n}\n\nexport default component(() =>\n    Expanded({\n        child: Container({\n            color: Color.hex(\"#1a1a2e\"),\n            padding: 24,\n            children: [\n                Column({\n                    mainAlignment: MainAxisAlignment.Start,\n                    crossAlignment: CrossAxisAlignment.Stretch,\n                    children: [\n                        Row({\n                            mainAlignment: MainAxisAlignment.Center,\n                            children: TABS.map((c) =>\n                                PointerInteract({\n                                    onClick: mutate(({ set }, _ev) =>\n                                        set(tab$, c),\n                                    ),\n                                    child: Container({\n                                        color: Color.hex(HEX[c]),\n                                        padding: 12,\n                                        children: [\n                                            Text({\n                                                text: c,\n                                                fontSize: 18,\n                                                color: Color.hex(\"#ffffff\"),\n                                            }),\n                                        ],\n                                    }),\n                                }),\n                            ),\n                        }),\n                        Container({ height: 16 }),\n                        Expanded({\n                            child: Switch({\n                                value: tab$,\n                                cases: [\n                                    {\n                                        key: \"red\",\n                                        child: () =>\n                                            coloredPanel(\n                                                \"Switch: RED\",\n                                                HEX.red,\n                                            ),\n                                    },\n                                    {\n                                        key: \"green\",\n                                        child: () =>\n                                            coloredPanel(\n                                                \"Switch: GREEN\",\n                                                HEX.green,\n                                            ),\n                                    },\n                                    {\n                                        key: \"blue\",\n                                        child: () =>\n                                            coloredPanel(\n                                                \"Switch: BLUE\",\n                                                HEX.blue,\n                                            ),\n                                    },\n                                ],\n                            }),\n                        }),\n                        Container({ height: 16 }),\n                        Container({\n                            height: 60,\n                            color: Color.hex(\"#0f172a\"),\n                            alignment: Alignment.Center,\n                            children: [\n                                Text({\n                                    text: derive(\n                                        () =>\n                                            `Switch sees: ${get(tab$).toUpperCase()}`,\n                                    ),\n                                    fontSize: 20,\n                                    color: Color.hex(\"#e2e8f0\"),\n                                }),\n                            ],\n                        }),\n                    ],\n                }),\n            ],\n        }),\n    }),\n);\n",
    },
